import{_ as e,o as a,c as o,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"Storage","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Storage | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/storage"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Storage | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/storage"}]]},"headers":[],"relativePath":"user-guide/storage.md","filePath":"user-guide/storage.md","lastUpdated":1787594009000}'),n={name:"user-guide/storage.md"};function d(s,t,l,c,i,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h1><p>Workspace content storage for chat attachments, feedback screenshots, lead imports, and <strong>Documents</strong> library files. Logos, favicons, and profile avatars stay on the app server and do <strong>not</strong> count toward this quota.</p><h2 id="enable-storage" tabindex="-1">Enable Storage <a class="header-anchor" href="#enable-storage" aria-label="Permalink to &quot;Enable Storage&quot;">​</a></h2><ol><li>Open <strong>Marketplace</strong></li><li>Find <strong>Storage</strong> (free) under the Storage category</li><li>Click <strong>Install</strong></li></ol><p>New workspaces start with <strong>0 GB</strong> of content storage until Storage is installed. Installing <strong>Team Chat</strong> also installs free Storage automatically so chat attachments keep working. Workspaces that already existed when Storage shipped were granted the free module automatically (grandfather migration).</p><p>Permission <strong>View storage</strong> (<code>storage.view</code>) opens Settings → Storage. Workspace admins get view + manage by default.</p><h2 id="allowance" tabindex="-1">Allowance <a class="header-anchor" href="#allowance" aria-label="Permalink to &quot;Allowance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>SKU</th><th>Slug</th><th>Monthly (USD)</th><th>Yearly (USD)</th><th>Total allowance</th></tr></thead><tbody><tr><td>Storage (free)</td><td><code>storage</code></td><td>$0</td><td>$0</td><td><strong>1 GB</strong></td></tr><tr><td>Storage 10 GB</td><td><code>storage-10</code></td><td>$4</td><td>$40</td><td>10 GB</td></tr><tr><td>Storage 50 GB</td><td><code>storage-50</code></td><td>$12</td><td>$120</td><td>50 GB</td></tr><tr><td>Storage 100 GB</td><td><code>storage-100</code></td><td>$20</td><td>$200</td><td>100 GB</td></tr><tr><td>Storage 500 GB</td><td><code>storage-500</code></td><td>$75</td><td>$750</td><td>500 GB</td></tr><tr><td>Storage 1000 GB</td><td><code>storage-1000</code></td><td>$120</td><td>$1200</td><td>1000 GB</td></tr></tbody></table><p>Pack size is the <strong>total</strong> workspace allowance (not added on top of the free 1 GB). Only <strong>one</strong> capacity pack can be active at a time — cancel the current pack before purchasing another.</p><h2 id="upgrade-change-pack" tabindex="-1">Upgrade / change pack <a class="header-anchor" href="#upgrade-change-pack" aria-label="Permalink to &quot;Upgrade / change pack&quot;">​</a></h2><ol><li>If another pack is already active, open that pack in Marketplace and <strong>Cancel subscription</strong></li><li>Purchase the new pack size (requires free Storage installed)</li><li>Gateway product mapping must exist for billable packs (Stripe / Creem) before checkout succeeds</li></ol><p>Cancelling a pack returns the workspace to the free 1 GB (while <code>storage</code> remains installed). Cancelling free Storage while a pack is still active is blocked by the pack’s required dependency.</p><h2 id="what-counts" tabindex="-1">What counts <a class="header-anchor" href="#what-counts" aria-label="Permalink to &quot;What counts&quot;">​</a></h2><p><strong>Included in quota</strong></p><ul><li>Team Chat message attachments</li><li>Feedback screenshots / attachments</li><li>Lead import source files (and generated error reports when present)</li><li>Documents module files (<code>documents.size_bytes</code> for non-deleted documents)</li></ul><p><strong>Not included</strong></p><ul><li>Workspace / Central branding logos and favicons</li><li>Profile avatars</li><li>Soft-deleted Documents (until restored; force-delete removes the object)</li></ul><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><strong>Settings → Storage</strong> shows used bytes, allowance, percent used, and the current pack (or Free 1 GB). Use <strong>Upgrade storage</strong> to open Marketplace.</p><h2 id="when-uploads-fail" tabindex="-1">When uploads fail <a class="header-anchor" href="#when-uploads-fail" aria-label="Permalink to &quot;When uploads fail&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Message</th></tr></thead><tbody><tr><td>Storage not installed</td><td>Install the free Storage module (<code>STORAGE_REQUIRED</code>)</td></tr><tr><td>Over quota</td><td>Upgrade storage pack or free space (<code>STORAGE_QUOTA_EXCEEDED</code>)</td></tr><tr><td>Another pack already active</td><td>Cancel the current pack first (<code>STORAGE_PACK_CONFLICT</code>)</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/user-guide/storage-overview">Storage overview</a></li><li><a href="/user-guide/documents">Documents</a> (bytes count toward this quota; requires Storage)</li></ul>',23)])])}const u=e(n,[["render",d]]);export{p as __pageData,u as default};
